(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.02+t*0.3)*15+Math.cos(y*0.015-t*0.2)*10;
  const w1y = Math.cos(y*0.02-t*0.25)*15+Math.sin(x*0.018+t*0.35)*10;
  const w2x = Math.sin(w1x*0.03+t*0.15)*8+Math.cos(w1y*0.02-t*0.1)*6;
  const w2y = Math.cos(w1y*0.03-t*0.12)*8+Math.sin(w1x*0.025+t*0.18)*6;
  const sx = x+w1x+w2x, sy = y+w1y+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100,80+Math.cos(t*0.4)*50,0.08,2.0,1.0],
    [320+Math.cos(t*0.5)*100,160+Math.sin(t*0.7)*50,0.1,1.7,0.8],
    [240+Math.sin(t*0.3+2)*140,120+Math.cos(t*0.5+1)*90,0.06,2.3,1.2],
    [120+Math.cos(t*0.8+1)*80,180+Math.sin(t*0.6+3)*60,0.12,1.5,0.7],
    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.07,2.6,1.1],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.09,1.9,0.9],
    [80+Math.sin(t*0.45+3)*60,40+Math.cos(t*0.65+2)*40,0.14,1.3,0.6],
    [400+Math.cos(t*0.55+1)*70,200+Math.sin(t*0.75+4)*50,0.05,2.8,1.3],
    [200+Math.sin(t*0.25+6)*110,100+Math.cos(t*0.45+3)*70,0.09,2.1,1.0]
  ];
  let aS=0,iS=0,mS=0;
  for(const[sX,sY,f,sp,amp]of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS+=Math.sin(d*f-t*sp)*amp;
    iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5)*amp;
    mS+=Math.sin(d*f*0.5-t*sp*0.4+3.0)*amp*0.5;
  }
  const n=src.length,act=aS/n,inh=iS/n,mod=mS/n;
  const bg=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2
    +Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2
    +Math.sin(sx*0.06+t*0.3)*Math.cos(sy*0.05-t*0.4)*0.15;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2),ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2)
    +Math.sin(dist*0.07-ang*2+t*0.8)*0.6)*0.3;
  const reaction=Math.tanh((act-inh*0.7+bg*0.3+spiral+mod*0.4)*2.2);
  const cell=Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)
    +Math.sin((sx+sy)*0.1+t)*0.5
    +Math.sin(sx*0.08-t*0.3)*Math.cos(sy*0.12+t*0.2)*0.3)*1.5)*0.3;
  const detail=Math.sin(sx*0.3+sy*0.2+t*3)*Math.sin(sx*0.2-sy*0.3-t*2.5)*0.15;
  const blend=reaction*0.6+cell*0.25+detail*0.15,v=blend*0.5+0.5;
  const pal=[[5,10,45],[10,45,85],[15,90,120],[25,140,130],[80,170,100],[180,180,60],[220,160,50],[210,110,55],[180,60,60],[130,35,70],[70,20,65],[30,12,50],[5,10,45]];
  const sample=(offset)=>{
    const vv=Math.max(0,Math.min(1,v+offset));
    const ii=vv*(pal.length-1),jj=Math.min(ii|0,pal.length-2),ff=ii-jj;
    return[pal[jj][0]+(pal[jj+1][0]-pal[jj][0])*ff,
           pal[jj][1]+(pal[jj+1][1]-pal[jj][1])*ff,
           pal[jj][2]+(pal[jj+1][2]-pal[jj][2])*ff];
  };
  const base=sample(0),rOff=sample(reaction*0.012),bOff=sample(-reaction*0.012);
  const lum=0.8+Math.sin(reaction*Math.PI)*0.2;
  const edge=Math.abs(reaction)>0.7?1.15:1.0;
  const vig=1.0-Math.sqrt((x-cx)**2+(y-cy)**2)/350*0.15;
  const m=lum*edge*vig;
  return[Math.min(255,rOff[0]*m)|0,Math.min(255,base[1]*m)|0,Math.min(255,bOff[2]*m)|0];
}
